export const InvalidParts: Story = {
  args: {
    value: "1990-13-40",
    isValid: false,
  },
  play: async ({ canvasElement }) => {
    const canvas = within(canvasElement);
    await expect(canvas.getByRole("textbox", { name: /År$/ })).not.toHaveAttribute("aria-invalid");
    await expect(canvas.getByRole("textbox", { name: "Månad" })).toHaveAttribute("aria-invalid", "true");
    await expect(canvas.getByRole("textbox", { name: "Dag" })).toHaveAttribute("aria-invalid", "true");
    await waitFor(() => expect(canvas.getByText("Vänligen ange ett giltigt födelsedatum")).toBeVisible());
  },
};

const onChangeSpy = fn();

export const TestTypeDate: Story = {
  args: {
    onChange: onChangeSpy,
  },
  play: async ({ canvasElement }) => {
    onChangeSpy.mockClear();
    const canvas = within(canvasElement);
    const monthInput = canvas.getByRole("textbox", { name: "Månad" });
    const dayInput = canvas.getByRole("textbox", { name: "Dag" });

    await userEvent.type(canvas.getByRole("textbox", { name: /År$/ }), "1990");
    await expect(monthInput).toHaveFocus();
    await userEvent.type(monthInput, "05");
    await expect(dayInput).toHaveFocus();
    await userEvent.type(dayInput, "17");
    await waitFor(() => expect(onChangeSpy).toHaveBeenCalledWith("dateOfBirth", "1990-05-17"));
  },
};
